  noAge <- data.frame(
    id = c("A", "B"), sex = c("M", "F"), stringsAsFactors = FALSE
  )
  expect_no_warning(res <- getPedMaxAge(noAge))
  expect_identical(res, NA_real_)
})

test_that("getPedMaxAge returns NA_real_ without warning when every age is NA", {
  allNaDouble <- data.frame(age = c(NA_real_, NA_real_))
  allNaLogical <- data.frame(age = c(NA, NA))
  expect_no_warning(resDouble <- getPedMaxAge(allNaDouble))
  expect_no_warning(resLogical <- getPedMaxAge(allNaLogical))
  expect_identical(resDouble, NA_real_)
  expect_identical(resLogical, NA_real_)
})

