  # Issue #121 (S314): the off-diagonal > 0.5 advisory (checkKinshipOverrides)
  # is emitted before the strict error -- once per validation pass, so assert
  # that it fired, not how many times, and capture it instead of letting it
  # escape as an unasserted warning.
  warns <- character(0L)
  expect_error(
    withCallingHandlers(
      suppressMessages(gvaConvergence(fx$ped,
        pop = fx$pop, nMax = 800L, seed = 11L, kinshipOverrides = badVal
      )),
      warning = function(w) {
        warns <<- c(warns, conditionMessage(w))
        invokeRestart("muffleWarning")
      }
    ),
    "above the maximum"
  )
  expect_true(any(grepl("off-diagonal value\\(s\\) > 0.5", warns)))
})

